import { setTimeout as tunda } from 'node:timers/promises';

console.log(await tunda(10, 'tunda selesai'));

const ac = new AbortController();
setTimeout(() => ac.abort(), 10);
try {
  await tunda(1000, 'tidak akan tercetak', { signal: ac.signal });
} catch (e) {
  console.log(e.name, e.code);
}

async function denganBatas(janji, ms) {
  const batas = tunda(ms).then(() => {
    throw new Error(`Lebih dari ${ms} ms`);
  });
  return Promise.race([janji, batas]);
}
try {
  await denganBatas(tunda(50, 'lambat'), 20);
} catch (e) {
  console.log(e.message);
}
console.log(await denganBatas(tunda(5, 'cepat'), 20));

