import { setTimeout as tunda } from 'node:timers/promises';
async function batasi(janji, ms) {
  const habis = tunda(ms).then(() => {
    throw new Error('Waktu habis');
  });
  return Promise.race([janji, habis]);
}
try {
  await batasi(tunda(50, 'ok'), 10);
} catch (e) {
  console.log(e.message);
}
